import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 4
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
    ))

    # Locate the first nonblank logical record with the expected header width.
    header_index = None
    fallback_index = None
    for index, record in enumerate(records):
        if not any(field.strip() for field in record):
            continue
        if ";".join(record).strip().casefold() == "sep=;":
            continue
        if fallback_index is None:
            fallback_index = index
        if len(record) == expected_width:
            header_index = index
            break

    if header_index is None:
        header_index = fallback_index
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    # Preserve surplus fields in extra columns and pad short records.
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
